import 'package:flutter/widgets.dart';
import 'package:get/get.dart';

/// Hệ thống đa ngôn ngữ (GetX i18n).
///
/// Mở rộng thêm ngôn ngữ trong tương lai chỉ cần:
///   1. Thêm map `_xx` bên dưới (đủ key như `_en`).
///   2. Thêm `'xx_YY': _xx` vào [keys].
///   3. Thêm `Locale('xx','YY')` vào [supported] + tên vào [languageNames].
/// Test `app_translations_test.dart` sẽ tự kiểm mọi ngôn ngữ có ĐỦ key.
class AppTranslations extends Translations {
  static const Locale fallback = Locale('en', 'US');

  /// Danh sách ngôn ngữ đang hỗ trợ (default đầu tiên = English).
  static const List<Locale> supported = [
    Locale('en', 'US'),
    Locale('vi', 'VN'),
    Locale('es', 'ES'),
    Locale('fr', 'FR'),
    Locale('de', 'DE'),
    Locale('pt', 'BR'),
    Locale('ru', 'RU'),
    Locale('zh', 'CN'),
    Locale('ja', 'JP'),
    Locale('ko', 'KR'),
    Locale('it', 'IT'),
    Locale('id', 'ID'),
    Locale('th', 'TH'),
    Locale('hi', 'IN'),
    Locale('ar', 'SA'),
    Locale('tr', 'TR'),
    Locale('nl', 'NL'),
    Locale('pl', 'PL'),
    Locale('fil', 'PH'),
    Locale('ms', 'MY'),
    Locale('uk', 'UA'),
    Locale('bn', 'BD'),
  ];

  /// Tên hiển thị của từng ngôn ngữ (theo chính ngôn ngữ đó — native name).
  static const Map<String, String> languageNames = {
    'en_US': 'English',
    'vi_VN': 'Tiếng Việt',
    'es_ES': 'Español',
    'fr_FR': 'Français',
    'de_DE': 'Deutsch',
    'pt_BR': 'Português',
    'ru_RU': 'Русский',
    'zh_CN': '中文',
    'ja_JP': '日本語',
    'ko_KR': '한국어',
    'it_IT': 'Italiano',
    'id_ID': 'Bahasa Indonesia',
    'th_TH': 'ไทย',
    'hi_IN': 'हिन्दी',
    'ar_SA': 'العربية',
    'tr_TR': 'Türkçe',
    'nl_NL': 'Nederlands',
    'pl_PL': 'Polski',
    'fil_PH': 'Filipino',
    'ms_MY': 'Bahasa Melayu',
    'uk_UA': 'Українська',
    'bn_BD': 'বাংলা',
  };

  static String codeOf(Locale l) => '${l.languageCode}_${l.countryCode}';

  @override
  Map<String, Map<String, String>> get keys {
    const base = <String, Map<String, String>>{
      'en_US': _en,
      'vi_VN': _vi,
      'es_ES': _es,
      'fr_FR': _fr,
      'de_DE': _de,
      'pt_BR': _pt,
      'ru_RU': _ru,
      'zh_CN': _zh,
      'ja_JP': _ja,
      'ko_KR': _ko,
      'it_IT': _it,
      'id_ID': _id,
      'th_TH': _th,
      'hi_IN': _hi,
      'ar_SA': _ar,
      'tr_TR': _tr,
      'nl_NL': _nl,
      'pl_PL': _pl,
      'fil_PH': _fil,
      'ms_MY': _ms,
      'uk_UA': _uk,
      'bn_BD': _bn,
    };
    // Key tính năng mới (Wave 4): merge _extraEn (mặc định/fallback) rồi override
    // bằng bản dịch riêng từng ngôn ngữ trong [_extraByLang] (đủ 22 ngôn ngữ).
    return {
      for (final e in base.entries)
        e.key: {
          ...e.value,
          ..._extraEn,
          ...?_extraByLang[e.key],
          // Wave 6 (en+vi nằm trong _extraEn/_extraVi; 20 ngôn ngữ ở _w6ByLang)
          ...?_w6ByLang[e.key],
          ...?_w8ByLang[e.key],
          ...?_w14ByLang[e.key],
          ...?_w15ByLang[e.key],
          ...?_w19ByLang[e.key],
          ...?_w184ByLang[e.key],
          ...?_w182ByLang[e.key],
          ...?_w183ByLang[e.key],
          ...?_w20ByLang[e.key],
          ...?_w21ByLang[e.key],
          ...?_w22ByLang[e.key],
          ...?_w23ByLang[e.key],
          ...?_w25ByLang[e.key],
          ...?_w26ByLang[e.key],
          ...?_w253ByLang[e.key],
          ...?_w254ByLang[e.key],
          ...?_w252ByLang[e.key],
          ...?_w24bByLang[e.key],
          ...?_w281ByLang[e.key],
        },
    };
  }

  /// Bản dịch key Wave 4 theo từng ngôn ngữ (en dùng [_extraEn] làm gốc).
  static const Map<String, Map<String, String>> _extraByLang = {
    'vi_VN': _extraVi,
    'es_ES': _extraEs,
    'fr_FR': _extraFr,
    'de_DE': _extraDe,
    'pt_BR': _extraPt,
    'ru_RU': _extraRu,
    'zh_CN': _extraZh,
    'ja_JP': _extraJa,
    'ko_KR': _extraKo,
    'it_IT': _extraIt,
    'id_ID': _extraId,
    'th_TH': _extraTh,
    'hi_IN': _extraHi,
    'ar_SA': _extraAr,
    'tr_TR': _extraTr,
    'nl_NL': _extraNl,
    'pl_PL': _extraPl,
    'fil_PH': _extraFil,
    'ms_MY': _extraMs,
    'uk_UA': _extraUk,
    'bn_BD': _extraBn,
  };

