    'story_w1_outro_l2': 'Un impulso magenta chiama da lontano. Seguilo...',
    'story_w2_intro_title': 'L\'Impulso Magenta',
    'story_w2_intro_l1': 'Sono Vera. Senti quel battito? È l\'Impulso Magenta.',
    'story_w2_intro_l2': 'Abbina a ritmo e il regno danzerà con te.',
