    'guide_story_title': 'Historia',
    'guide_story_body':
        'Poznaj neonowego strażnika w każdym świecie. Witają cię, dopingują w połowie drogi i wysyłają do kolejnej krainy, gdy zagłębiasz się dalej.',
    'story_w1_intro_title': 'Cyjanowa Mgławica',
    'story_w1_intro_l1':
        'Witaj, podróżniku. Jestem Luma, światło Cyjanowej Mgławicy.',
    'story_w1_intro_l2':
        'Klejnoty tutaj przygasły. Dopasuj je, by przywrócić blask!',
    'story_w1_mid_title': 'Powrót Iskry',
    'story_w1_mid_l1': 'Mgławica znów lśni — masz dar.',
    'story_w1_mid_l2': 'Ale głębsze krainy czekają. Nie poddawaj się!',
    'story_w1_outro_title': 'Mgławica Odrestaurowana',
    'story_w1_outro_l1': 'Cyjanowa Mgławica lśni jak nigdy dotąd. Dziękuję!',
    'story_w1_outro_l2': 'Magentowy puls woła z oddali. Podążaj za nim...',
    'story_w2_intro_title': 'Magentowy Puls',
    'story_w2_intro_l1': 'Jestem Vera. Czujesz to bicie? To Magentowy Puls.',
    'story_w2_intro_l2': 'Dopasowuj w rytmie, a kraina zatańczy z tobą.',
    'story_w2_mid_title': 'W Rytmie',
    'story_w2_mid_l1': 'Twoje kombosy odbijają się echem przez puls — piękne!',
    'story_w2_mid_l2': 'Połowa podróży za tobą. Rytm staje się coraz dziksz.',
    'story_w2_outro_title': 'Stabilne Bicie',
    'story_w2_outro_l1': 'Puls jest znów stabilny i jasny. Niesamowite!',
    'story_w2_outro_l2': 'Iskry zielonego obwodu migoczą przed tobą.',
    'story_w3_intro_title': 'Limonkowy Obwód',
    'story_w3_intro_l1': 'Bip! Jestem Cir, strażnik Limonkowego Obwodu.',
    'story_w3_intro_l2':
