    'story_w3_outro_l2': 'Płonąca bursztynowa kometa przecina mrok...',
    'story_w4_intro_title': 'Bursztynowa Kometa',
    'story_w4_intro_l1': 'Jestem Ember, jeźdźczyni Bursztynowej Komety.',
    'story_w4_intro_l2': 'Przebijaj się przez klejnoty, zanim kometa zgaśnie!',
    'story_w4_mid_title': 'Płonący Blask',
